#!/usr/bin/env bash
set -euo pipefail
# Applies source-schema renames with git mv and installs prepared source-schema edits.
# Usage: cd /path/to/pub.lib.General; bash /path/to/apply-naming-convention-intf-migration.sh
# The overlay archive must be adjacent to this script.
overlay="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/naming-convention-intf-migration-overlay.tgz"
[[ -f "$overlay" ]] || { echo "Missing overlay archive: $overlay" >&2; exit 2; }
root="$(git rev-parse --show-toplevel)"
cd "$root"
[[ -f naming/convention/intf/modustro-artifact.yml ]] || { echo "Run inside pub.lib.General" >&2; exit 2; }

# Check all expected input paths before any changes (protect custom work and avoid partially moved files).
while IFS="|" read -r source destination sha; do
    [[ -f "$source" ]] || { echo "Missing source: $source" >&2; exit 3; }
    [[ ! -e "$destination" ]] || { echo "Already exists: $destination" >&2; exit 3; }
    git ls-files --error-unmatch -- "$source" >/dev/null || { echo "Not tracked: $source" >&2; exit 3; }
    actual="$(sha256sum "$source")"; actual="${actual%% *}"
    [[ "$actual" == "$sha" ]] || { echo "Unexpected local edits in $source; stop to merge manually" >&2; exit 3; }
done <<'CHECKSUMS'
